tad_contract = importlib.import_module('con_rubix_test_tad')
vault_contract = importlib.import_module('con_rubix_test_vault')
__rate = Hash(contract='con_rubix_test_stake', name='rate')
__balances = Hash(default_value=0, contract='con_rubix_test_stake', name=
    'balances')
__metadata = Hash(contract='con_rubix_test_stake', name='metadata')
__total_minted = Variable(contract='con_rubix_test_stake', name='total_minted')
__operator = Variable(contract='con_rubix_test_stake', name='operator')


def ____():
    __operator.set(ctx.caller)
    __rate['start_time'] = get_timestamp()
    __rate['rate'] = decimal('1.0000000015469297')
    __rate['start_price'] = 1
    __metadata['token_name'] = 'Staked tad'
    __metadata['token_symbol'] = 'stad'
    __metadata['token_logo_url'] = 'image.site'
    __metadata['operator'] = ctx.caller
    __total_minted.set(0)


@__export('con_rubix_test_stake')
def get_timestamp():
    td = now - datetime.datetime(1970, 1, 1, 0, 0, 0)
    return td.seconds


@__export('con_rubix_test_stake')
def stake(amount: float):
    assert amount > 0, 'Stake amount must be positive!'
    tad_contract.transfer_from(to=ctx.this, amount=amount, main_account=ctx
        .caller)
    amount_minted = amount / get_price()
    total = __total_minted.get() + amount_minted
    __total_minted.set(total)
    __balances[ctx.caller] += amount_minted
    return amount_minted


@__export('con_rubix_test_stake')
def withdraw_stake(amount: float):
    assert amount > 0, 'Stake amount must be positive!'
    assert __balances[ctx.caller] >= amount, 'Not enough coins to withdraw!'
    __balances[ctx.caller] -= amount
    current_price = get_price()
    return_amount = current_price * amount
    supply = __total_minted.get()
    current_average = supply / tad_contract.balance_of(ctx.this)
    transfer_away_amount = amount * current_average
    __total_minted.set(supply - amount)
    if return_amount - transfer_away_amount > 0:
        vault_contract.mint_rewards(amount=return_amount - transfer_away_amount
            )
    tad_contract.transfer(amount=return_amount, to=ctx.caller)
    return return_amount


@__export('con_rubix_test_stake')
def change_rate(new_rate: float):
    __assert_owner()
    assert new_rate >= 0, 'Cannot have negative staking!'
    current_price = get_price()
    __rate['start_time'] = get_timestamp()
    __rate['rate'] = new_rate
    __rate['start_price'] = current_price


@__export('con_rubix_test_stake')
def transfer(amount: float, to: str):
    assert amount > 0, 'Cannot send negative balances!'
    sender = ctx.caller
    assert __balances[sender] >= amount, 'Not enough coins to send!'
    __balances[sender] -= amount
    __balances[to] += amount


@__export('con_rubix_test_stake')
def balance_of(account: str):
    return __balances[account]


@__export('con_rubix_test_stake')
def allowance(owner: str, spender: str):
    return __balances[owner, spender]


@__export('con_rubix_test_stake')
def approve(amount: float, to: str):
    assert amount > 0, 'Cannot send negative balances!'
    sender = ctx.caller
    assert __balances[sender
        ] >= amount, 'Cannot approve balance that exceeds total balance!'
    __balances[sender, to] += amount
    return __balances[sender, to]


@__export('con_rubix_test_stake')
def transfer_from(amount: float, to: str, main_account: str):
    assert amount > 0, 'Cannot send negative balances!'
    sender = ctx.caller
    assert __balances[main_account] >= amount, 'Not enough coins to send!'
    assert __balances[main_account, sender
        ] >= amount, 'Not enough coins approved to send! You have {} and are trying to spend {}'.format(
        __balances[main_account, sender], amount)
    __balances[main_account, sender] -= amount
    __balances[main_account] -= amount
    __balances[to] += amount


@__export('con_rubix_test_stake')
def get_price():
    return __rate['start_price'] * __rate['rate'] ** (get_timestamp() -
        __rate['start_time'])


@__export('con_rubix_test_stake')
def change_metadata(key: str, value: Any):
    assert ctx.caller == __metadata['operator'
        ], 'Only operator can set metadata!'
    __metadata[key] = value


@__export('con_rubix_test_stake')
def change_owner(new_owner: str):
    __assert_owner()
    __operator.set(new_owner)


def __assert_owner():
    assert ctx.caller == __operator.get(), 'Only operator can call!'
